class Solution {
public:
    long long maxSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> minPrefix(k, 1e18);
        minPrefix[(k - 1) % k] = 0;

        long long maxSum = -1e18;
        long long currSum = 0;

        for (int i = 0; i < n; ++i) {
            currSum += nums[i];
            int rem = i % k;
            if (minPrefix[rem] < 1e17) {
                maxSum = max(maxSum, currSum - minPrefix[rem]);
            }
            minPrefix[rem] = min(minPrefix[rem], currSum);
        }
        return maxSum;
    }
};

