var maxSubarraySum = function(nums, k) {
    const n = nums.length;
    const minPrefix = new Array(k).fill(Infinity);
    minPrefix[(k - 1) % k] = 0;

    let maxSum = -Infinity;
    let currSum = 0;

    for (let i = 0; i < n; i++) {
        currSum += nums[i];
        const rem = i % k;
        if (minPrefix[rem] !== Infinity) {
            maxSum = Math.max(maxSum, currSum - minPrefix[rem]);
        }
        minPrefix[rem] = Math.min(minPrefix[rem], currSum);
    }
    return maxSum;
};
